//! Polygon triangulation by ear clipping, a from-scratch Rust port of the
//! Mapbox `earcut` algorithm (earcut.hpp / earcut.js behavior), using only
//! the standard library.
//!
//! The polygon is a list of rings; the first ring is the outer boundary and
//! every subsequent ring is treated as a hole. Returns a flat list of
//! triangle vertex indices into the concatenated ring vertices.

/// Above this total vertex count, z-order hashing is used to speed up
/// the "is ear" checks.
const THRESHOLD: usize = 80;

#[derive(Clone)]
struct Node {
    /// Original vertex index in the concatenated polygon.
    i: u32,
    x: f64,
    y: f64,
    /// Z-order curve value.
    z: i32,
    /// Previous/next vertex node in the polygon ring (circular list).
    prev: usize,
    next: usize,
    /// Previous/next node in z-order.
    prev_z: Option<usize>,
    next_z: Option<usize>,
    /// Whether this is a steiner point.
    steiner: bool,
}

pub struct Earcut {
    /// Arena of all nodes; nodes are never freed, only unlinked.
    nodes: Vec<Node>,
    pub indices: Vec<u32>,
    vertices: usize,
    min_x: f64,
    min_y: f64,
    inv_size: f64,
}

/// Triangulate the given polygon; mirrors `mapbox::earcut<uint32_t>`.
pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut earcut = Earcut::new();
    earcut.run(polygon);
    earcut.indices
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            nodes: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
            min_x: 0.0,
            min_y: 0.0,
            inv_size: 0.0,
        }
    }

    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        self.indices.clear();
        self.nodes.clear();
        self.vertices = 0;
        self.inv_size = 0.0;

        if points.is_empty() {
            return;
        }
        let has_holes = points.len() > 1;

        let outer_node = match self.linked_list(&points[0], true) {
            Some(node) => node,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        let mut outer_node = outer_node;
        if has_holes {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        // if the shape is not too simple, we'll use z-order curve hash later;
        // calculate polygon bbox
        if self.vertices > THRESHOLD && !points[0].is_empty() {
            let mut min_x = points[0][0][0];
            let mut max_x = min_x;
            let mut min_y = points[0][0][1];
            let mut max_y = min_y;
            for p in &points[0][1..] {
                if p[0] < min_x {
                    min_x = p[0];
                }
                if p[1] < min_y {
                    min_y = p[1];
                }
                if p[0] > max_x {
                    max_x = p[0];
                }
                if p[1] > max_y {
                    max_y = p[1];
                }
            }

            // min_x, min_y and inv_size are later used to transform coords
            // into integers for z-order calculation
            let max = (max_x - min_x).max(max_y - min_y);
            self.min_x = min_x;
            self.min_y = min_y;
            self.inv_size = if max != 0.0 { 1.0 / max } else { 0.0 };
        }

        self.earcut_linked(Some(outer_node), 0);
    }

    /// Create a circular doubly linked list from a polygon ring in the
    /// specified winding order.
    fn linked_list(&mut self, ring: &[[f64; 2]], clockwise: bool) -> Option<usize> {
        let len = ring.len();

        // calculate original winding order of a polygon ring
        let mut sum = 0.0;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            sum += (ring[j][0] - ring[i][0]) * (ring[i][1] + ring[j][1]);
            j = i;
        }

        // link points into circular doubly-linked list in the specified order
        let mut last: Option<usize> = None;
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = Some(self.insert_node(
                    (self.vertices + i) as u32,
                    ring[i][0],
                    ring[i][1],
                    last,
                ));
            }
        } else {
            for i in (0..len).rev() {
                last = Some(self.insert_node(
                    (self.vertices + i) as u32,
                    ring[i][0],
                    ring[i][1],
                    last,
                ));
            }
        }

        if let Some(l) = last {
            let lnext = self.nodes[l].next;
            if self.equals(l, lnext) {
                self.remove_node(l);
                last = Some(self.nodes[l].next);
            }
        }

        self.vertices += len;
        last
    }

    /// Eliminate colinear or duplicate points.
    fn filter_points(&mut self, start: Option<usize>, end: Option<usize>) -> Option<usize> {
        let start = start?;
        let mut end = end.unwrap_or(start);

        let mut p = start;
        loop {
            let mut again = false;

            let pprev = self.nodes[p].prev;
            let pnext = self.nodes[p].next;
            if !self.nodes[p].steiner
                && (self.equals(p, pnext) || self.area(pprev, p, pnext) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }

            if !(again || p != end) {
                break;
            }
        }

        Some(end)
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
    fn earcut_linked(&mut self, ear: Option<usize>, pass: i32) {
        let mut ear = match ear {
            Some(e) => e,
            None => return,
        };

        // interlink polygon nodes in z-order
        if pass == 0 && self.inv_size != 0.0 {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.inv_size != 0.0 {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let filtered = self.filter_points(Some(ear), None);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small self-intersections locally
                    let filtered = self.filter_points(Some(ear), None);
                    ear = self.cure_local_intersections(filtered.unwrap());
                    self.earcut_linked(Some(ear), 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[ear].next.next;
        while p != self.nodes[ear].prev {
            if self.point_in_triangle_node(a, b, c, p)
                && self.area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = if ax < bx {
            if ax < cx {
                ax
            } else {
                cx
            }
        } else if bx < cx {
            bx
        } else {
            cx
        };
        let min_ty = if ay < by {
            if ay < cy {
                ay
            } else {
                cy
            }
        } else if by < cy {
            by
        } else {
            cy
        };
        let max_tx = if ax > bx {
            if ax > cx {
                ax
            } else {
                cx
            }
        } else if bx > cx {
            bx
        } else {
            cx
        };
        let max_ty = if ay > by {
            if ay > cy {
                ay
            } else {
                cy
            }
        } else if by > cy {
            by
        } else {
            cy
        };

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        let mut p = self.nodes[ear].prev_z;
        let mut n = self.nodes[ear].next_z;

        // look for points inside the triangle in both directions
        while let (Some(pi), Some(ni)) = (p, n) {
            if self.nodes[pi].z < min_z || self.nodes[ni].z > max_z {
                break;
            }

            if pi != self.nodes[ear].prev
                && pi != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[pi].x, self.nodes[pi].y)
                && self.area(self.nodes[pi].prev, pi, self.nodes[pi].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pi].prev_z;

            if ni != self.nodes[ear].prev
                && ni != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[ni].x, self.nodes[ni].y)
                && self.area(self.nodes[ni].prev, ni, self.nodes[ni].next) >= 0.0
            {
                return false;
            }
            n = self.nodes[ni].next_z;
        }

        // look for remaining points in decreasing z-order
        while let Some(pi) = p {
            if self.nodes[pi].z < min_z {
                break;
            }
            if pi != self.nodes[ear].prev
                && pi != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[pi].x, self.nodes[pi].y)
                && self.area(self.nodes[pi].prev, pi, self.nodes[pi].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pi].prev_z;
        }

        // look for remaining points in increasing z-order
        while let Some(ni) = n {
            if self.nodes[ni].z > max_z {
                break;
            }
            if ni != self.nodes[ear].prev
                && ni != self.nodes[ear].next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[ni].x, self.nodes[ni].y)
                && self.area(self.nodes[ni].prev, ni, self.nodes[ni].next) >= 0.0
            {
                return false;
            }
            n = self.nodes[ni].next_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut start = start;
        let mut p = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;

            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                let pnext = self.nodes[p].next;
                self.remove_node(p);
                self.remove_node(pnext);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(Some(p), None).unwrap()
    }

    /// Try splitting polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let an = self.nodes[a].next;
                    a = self.filter_points(Some(a), Some(an)).unwrap();
                    let cn = self.nodes[c].next;
                    let c = self.filter_points(Some(c), Some(cn)).unwrap();

                    // run earcut on each half
                    self.earcut_linked(Some(a), 0);
                    self.earcut_linked(Some(c), 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Link every hole into the outer loop, producing a single-ring polygon without holes.
    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
        let mut queue = Vec::new();
        for i in 1..points.len() {
            if let Some(list) = self.linked_list(&points[i], false) {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        queue.sort_by(|&a, &b| {
            self.nodes[a]
                .x
                .partial_cmp(&self.nodes[b].x)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // process holes from left to right
        let mut outer_node = outer_node;
        for hole in queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    /// Find a bridge between vertices that connects a hole with an outer ring and link it.
    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let outer_node = match self.find_hole_bridge(hole, outer_node) {
            Some(bridge) => bridge,
            None => return outer_node,
        };

        let bridge_reverse = self.split_polygon(outer_node, hole);

        // filter collinear points around the cuts
        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(Some(bridge_reverse), Some(br_next));
        let on_next = self.nodes[outer_node].next;
        self.filter_points(Some(outer_node), Some(on_next));

        outer_node
    }

    /// David Eberly's algorithm for finding a bridge between a hole and outer polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> Option<usize> {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m: Option<usize> = None;

        // find a segment intersected by a ray from the hole's leftmost point to the left;
        // segment's endpoint with lesser x will be potential connection point
        loop {
            let pn = self.nodes[p].next;
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (pnx, pny) = (self.nodes[pn].x, self.nodes[pn].y);

            if hy <= py && hy >= pny && pny != py {
                let x = px + (hy - py) * (pnx - px) / (pny - py);
                if x <= hx && x > qx {
                    qx = x;
                    if x == hx {
                        if hy == py {
                            return Some(p);
                        }
                        if hy == pny {
                            return Some(pn);
                        }
                    }
                    m = Some(if px < pnx { p } else { pn });
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        let m0 = m?;

        // hole touches outer segment; pick leftmost endpoint
        if hx == qx {
            return Some(self.nodes[m0].prev);
        }

        // look for points inside the triangle of hole point, segment intersection and endpoint;
        // if there are no points found, we have a valid connection;
        // otherwise choose the point of the minimum angle with the ray as connection point
        let stop = m0;
        let mut m = m0;
        let mut tan_min = f64::INFINITY;

        p = self.nodes[m0].next;
        while p != stop {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (mx, my) = (self.nodes[m].x, self.nodes[m].y);

            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                // tangential
                let tan = (hy - py).abs() / (hx - px);

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > mx || (px == mx && self.sector_contains_sector(m, p)))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.nodes[p].next;
        }

        Some(m)
    }

    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes[m].prev, m, self.nodes[p].prev) < 0.0
            && self.area(self.nodes[p].next, m, self.nodes[m].next) < 0.0
    }

    /// Interlink polygon nodes in z-order.
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            let z = self.z_order(self.nodes[p].x, self.nodes[p].y);
            self.nodes[p].z = z;
            self.nodes[p].prev_z = Some(self.nodes[p].prev);
            self.nodes[p].next_z = Some(self.nodes[p].next);
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let ppz = self.nodes[p].prev_z.unwrap();
        self.nodes[ppz].next_z = None;
        self.nodes[p].prev_z = None;

        self.sort_linked(p);
    }

    /// Simon Tatham's linked list merge sort algorithm.
    fn sort_linked(&mut self, list: usize) -> usize {
        let mut in_size = 1usize;
        let mut list: Option<usize> = Some(list);

        loop {
            let mut p = list;
            list = None;
            let mut tail: Option<usize> = None;
            let mut num_merges = 0;

            while let Some(pi) = p {
                num_merges += 1;
                let mut q: Option<usize> = Some(pi);
                let mut p_size = 0usize;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q.unwrap()].next_z;
                    if q.is_none() {
                        break;
                    }
                }
                let mut q_size = in_size;

                while p_size > 0 || (q_size > 0 && q.is_some()) {
                    let e;
                    if p_size != 0
                        && (q_size == 0
                            || q.is_none()
                            || self.nodes[p.unwrap()].z <= self.nodes[q.unwrap()].z)
                    {
                        e = p.unwrap();
                        p = self.nodes[e].next_z;
                        p_size -= 1;
                    } else {
                        e = q.unwrap();
                        q = self.nodes[e].next_z;
                        q_size -= 1;
                    }

                    match tail {
                        Some(t) => self.nodes[t].next_z = Some(e),
                        None => list = Some(e),
                    }

                    self.nodes[e].prev_z = tail;
                    tail = Some(e);
                }

                p = q;
            }

            self.nodes[tail.unwrap()].next_z = None;
            in_size *= 2;

            if num_merges <= 1 {
                break;
            }
        }

        list.unwrap()
    }

    /// Z-order of a point given the bbox of the polygon.
    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = (32767.0 * (x_ - self.min_x) * self.inv_size) as i32;
        let mut y = (32767.0 * (y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF_00FF;
        x = (x | (x << 4)) & 0x0F0F_0F0F;
        x = (x | (x << 2)) & 0x3333_3333;
        x = (x | (x << 1)) & 0x5555_5555;

        y = (y | (y << 8)) & 0x00FF_00FF;
        y = (y | (y << 4)) & 0x0F0F_0F0F;
        y = (y | (y << 2)) & 0x3333_3333;
        y = (y | (y << 1)) & 0x5555_5555;

        x | (y << 1)
    }

    /// Find the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    fn point_in_triangle_node(&self, a: usize, b: usize, c: usize, p: usize) -> bool {
        point_in_triangle(
            self.nodes[a].x,
            self.nodes[a].y,
            self.nodes[b].x,
            self.nodes[b].y,
            self.nodes[c].x,
            self.nodes[c].y,
            self.nodes[p].x,
            self.nodes[p].y,
        )
    }

    /// Check if a diagonal between two polygon nodes is valid (lies inside the polygon).
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        self.nodes[self.nodes[a].next].i != self.nodes[b].i
            && self.nodes[self.nodes[a].prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(self.nodes[a].prev, a, self.nodes[b].prev) != 0.0
                    || self.area(a, self.nodes[b].prev, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(self.nodes[a].prev, a, self.nodes[a].next) > 0.0
                    && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0))
    }

    /// Signed area of a triangle (p, q, r).
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    /// Check if two points are equal.
    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    /// Check if two segments intersect.
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2))
            || (self.equals(p1, q2) && self.equals(p2, q1))
        {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    /// Check if a polygon diagonal intersects any polygon segments.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    /// Check if a polygon diagonal is locally inside the polygon.
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let aprev = self.nodes[a].prev;
        let anext = self.nodes[a].next;
        if self.area(aprev, a, anext) < 0.0 {
            self.area(a, b, anext) >= 0.0 && self.area(a, aprev, b) >= 0.0
        } else {
            self.area(a, b, aprev) < 0.0 || self.area(a, anext, b) < 0.0
        }
    }

    /// Check if the middle point of a polygon diagonal is inside the polygon.
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            let (px_, py_) = (self.nodes[p].x, self.nodes[p].y);
            let (pnx, pny) = (self.nodes[pn].x, self.nodes[pn].y);
            if ((py_ > py) != (pny > py))
                && pny != py_
                && (px < (pnx - px_) * (py - py_) / (pny - py_) + px_)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    /// Link two polygon vertices with a bridge; return the new node.
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let a2 = self.new_node(ai, ax, ay);
        let b2 = self.new_node(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    /// Create a node and optionally link it with a previous one in a circular list.
    fn new_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        let p = self.nodes.len();
        self.nodes.push(Node {
            i,
            x,
            y,
            z: 0,
            prev: p,
            next: p,
            prev_z: None,
            next_z: None,
            steiner: false,
        });
        p
    }

    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
        let p = self.new_node(i, x, y);

        if let Some(last) = last {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let pnext = self.nodes[p].next;
        let pprev = self.nodes[p].prev;
        self.nodes[pnext].prev = pprev;
        self.nodes[pprev].next = pnext;

        if let Some(ppz) = self.nodes[p].prev_z {
            self.nodes[ppz].next_z = self.nodes[p].next_z;
        }
        if let Some(pnz) = self.nodes[p].next_z {
            self.nodes[pnz].prev_z = self.nodes[p].prev_z;
        }
    }
}

/// Check if a point is inside a triangle.
fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

