//! Entry point mirroring `tests/test4.cpp` from the earcut.hpp test suite.
//!
//! Builds a "polygon" whose first ring is the square (0,0)-(n,n) and whose
//! remaining n-1 rings (treated as holes by the triangulator) are squares
//! offset by (2i, 2i), then prints the triangle indices.

#[path = "src/earcut.rs"]
mod earcut;

use std::io::Write;

/// Mimics C `std::atoi`: skips leading whitespace, accepts an optional sign,
/// then parses digits until the first non-digit; yields 0 for garbage input.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r') {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        if bytes[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut value: i64 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        value = value.wrapping_mul(10).wrapping_add((bytes[i] - b'0') as i64);
        i += 1;
    }
    sign.wrapping_mul(value) as i32
}

fn main() {
    let mut n: i32 = 4;
    let args: Vec<String> = std::env::args().collect();
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();

    for i in 0..n {
        let offset = (i * 2) as f64;
        let size = n as f64;
        polygon.push(vec![
            [offset, offset],
            [offset + size, offset],
            [offset + size, offset + size],
            [offset, offset + size],
        ]);
    }

    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    let mut line = String::new();
    for idx in indices {
        line.push_str(&idx.to_string());
        line.push(' ');
    }
    out.write_all(line.as_bytes()).unwrap();
}

