// Variant-search testbed for earcut behavior matching.
use std::cell::Cell;

#[derive(Clone, Copy, Default, Debug)]
struct Cfg {
    reflex_strict: bool,   // isEar: area > 0 => not ear (default: >= 0)
    block_strict: bool,    // blocking test: area > 0 (default: >= 0)
    hole_filter: u8,       // 0: (b,b.next),(o,o.next); 1: both full; 2: b full only; 3: o full only; 4: b std only; 5: o std only
    fhb_early: bool,       // x==hx early return (default true)
    fhb_hxqx_mprev: bool,  // hx==qx => m.prev (true) vs m (false)
    fhb_hx_neq: bool,      // hx != p.x guard (default true)
    fhb_tie: u8,           // 0: p.x>m.x ; 1: || (== && sector) ; 2: p.x>=m.x
    leftmost: u8,          // 0: x then y ; 1: x only strict ; 2: x only <=
    hole_forward: bool,
    outer_backward: bool,
    ray: u8,               // 0 std ; 1 no horiz exclusion ; 2: hy<p.y&&hy>=pn.y ; 3: hy<=p.y&&hy>pn.y
    elim_ret_filtered: bool,
}

#[derive(Clone)]
struct Node {
    i: u32,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    steiner: bool,
}

struct E {
    nodes: Vec<Node>,
    indices: Vec<u32>,
    vertices: usize,
    cfg: Cfg,
    budget: Cell<u64>,
    depth: Cell<u32>,
}

impl E {
    fn bail(&self) -> bool {
        if self.budget.get() == 0 {
            true
        } else {
            self.budget.set(self.budget.get() - 1);
            false
        }
    }

    fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        self.budget.set(2_000_000);
        self.depth.set(0);
        if points.is_empty() {
            return;
        }
        let has_holes = points.len() > 1;
        let outer_node = match self.linked_list(&points[0], !self.cfg.outer_backward) {
            Some(n) => n,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }
        let mut outer_node = outer_node;
        if has_holes {
            outer_node = self.eliminate_holes(points, outer_node);
        }
        self.earcut_linked(Some(outer_node), 0);
    }

    fn linked_list(&mut self, ring: &[[f64; 2]], clockwise: bool) -> Option<usize> {
        let len = ring.len();
        let mut sum = 0.0;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            sum += (ring[j][0] - ring[i][0]) * (ring[i][1] + ring[j][1]);
            j = i;
        }
        let mut last: Option<usize> = None;
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = Some(self.insert_node((self.vertices + i) as u32, ring[i][0], ring[i][1], last));
            }
        } else {
            for i in (0..len).rev() {
                last = Some(self.insert_node((self.vertices + i) as u32, ring[i][0], ring[i][1], last));
            }
        }
        if let Some(l) = last {
            let lnext = self.nodes[l].next;
            if self.equals(l, lnext) {
                self.remove_node(l);
                last = Some(self.nodes[l].next);
            }
        }
        self.vertices += len;
        last
    }

    fn filter_points(&mut self, start: Option<usize>, end: Option<usize>) -> Option<usize> {
        let start = start?;
        let mut end = end.unwrap_or(start);
        let mut p = start;
        loop {
            if self.bail() {
                return Some(end);
            }
            let mut again = false;
            let pprev = self.nodes[p].prev;
            let pnext = self.nodes[p].next;
            if !self.nodes[p].steiner && (self.equals(p, pnext) || self.area(pprev, p, pnext) == 0.0) {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;
                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = self.nodes[p].next;
            }
            if !(again || p != end) {
                break;
            }
        }
        Some(end)
    }

    fn earcut_linked(&mut self, ear: Option<usize>, pass: i32) {
        if self.depth.get() > 64 {
            return;
        }
        let mut ear = match ear {
            Some(e) => e,
            None => return,
        };
        let mut stop = ear;
        while self.nodes[ear].prev != self.nodes[ear].next {
            if self.bail() {
                return;
            }
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;
            if self.is_ear(ear) {
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);
                self.remove_node(ear);
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;
                continue;
            }
            ear = next;
            if ear == stop {
                self.depth.set(self.depth.get() + 1);
                if pass == 0 {
                    let f = self.filter_points(Some(ear), None);
                    self.earcut_linked(f, 1);
                } else if pass == 1 {
                    let f = self.filter_points(Some(ear), None);
                    let e = self.cure_local_intersections(f.unwrap());
                    self.earcut_linked(Some(e), 2);
                } else if pass == 2 {
                    self.split_earcut(ear);
                }
                self.depth.set(self.depth.get() - 1);
                break;
            }
        }
    }

    fn reflex_blocked(&self, v: f64) -> bool {
        if self.cfg.reflex_strict {
            v > 0.0
        } else {
            v >= 0.0
        }
    }
    fn block_hit(&self, v: f64) -> bool {
        if self.cfg.block_strict {
            v > 0.0
        } else {
            v >= 0.0
        }
    }

    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;
        if self.reflex_blocked(self.area(a, b, c)) {
            return false;
        }
        let mut p = self.nodes[self.nodes[ear].next].next;
        let mut guard = 0u64;
        while p != self.nodes[ear].prev {
            guard += 1;
            if guard > 100000 {
                return false;
            }
            if self.point_in_triangle_node(a, b, c, p)
                && self.block_hit(self.area(self.nodes[p].prev, p, self.nodes[p].next))
            {
                return false;
            }
            p = self.nodes[p].next;
        }
        true
    }

    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut start = start;
        let mut p = start;
        loop {
            if self.bail() {
                return p;
            }
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;
            if !self.equals(a, b)
                && self.intersects(a, p, self.nodes[p].next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);
                let pnext = self.nodes[p].next;
                self.remove_node(p);
                self.remove_node(pnext);
                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        self.filter_points(Some(p), None).unwrap()
    }

    fn split_earcut(&mut self, start: usize) {
        let mut a = start;
        loop {
            if self.bail() {
                return;
            }
            let mut b = self.nodes[self.nodes[a].next].next;
            let mut guard = 0u64;
            while b != self.nodes[a].prev {
                guard += 1;
                if guard > 100000 {
                    return;
                }
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    let c = self.split_polygon(a, b);
                    let an = self.nodes[a].next;
                    a = self.filter_points(Some(a), Some(an)).unwrap();
                    let cn = self.nodes[c].next;
                    let c = self.filter_points(Some(c), Some(cn)).unwrap();
                    self.earcut_linked(Some(a), 0);
                    self.earcut_linked(Some(c), 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
        let mut queue = Vec::new();
        for i in 1..points.len() {
            if let Some(list) = self.linked_list(&points[i], !self.cfg.hole_forward) {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }
        queue.sort_by(|&a, &b| {
            self.nodes[a]
                .x
                .partial_cmp(&self.nodes[b].x)
                .unwrap_or(std::cmp::Ordering::Equal)
        });
        let mut outer_node = outer_node;
        for hole in queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }
        outer_node
    }

    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let outer_node = match self.find_hole_bridge(hole, outer_node) {
            Some(b) => b,
            None => return outer_node,
        };
        let bridge_reverse = self.split_polygon(outer_node, hole);
        let r = match self.cfg.hole_filter {
            0 => {
                let brn = self.nodes[bridge_reverse].next;
                self.filter_points(Some(bridge_reverse), Some(brn));
                let onn = self.nodes[outer_node].next;
                self.filter_points(Some(outer_node), Some(onn))
            }
            1 => {
                self.filter_points(Some(bridge_reverse), None);
                self.filter_points(Some(outer_node), None)
            }
            2 => self.filter_points(Some(bridge_reverse), None),
            3 => self.filter_points(Some(outer_node), None),
            4 => {
                let brn = self.nodes[bridge_reverse].next;
                self.filter_points(Some(bridge_reverse), Some(brn))
            }
            _ => {
                let onn = self.nodes[outer_node].next;
                self.filter_points(Some(outer_node), Some(onn))
            }
        };
        if self.cfg.elim_ret_filtered {
            r.unwrap_or(outer_node)
        } else {
            outer_node
        }
    }

    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> Option<usize> {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m: Option<usize> = None;
        loop {
            if self.bail() {
                return None;
            }
            let pn = self.nodes[p].next;
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (pnx, pny) = (self.nodes[pn].x, self.nodes[pn].y);
            let cond = match self.cfg.ray {
                0 => hy <= py && hy >= pny && pny != py,
                1 => hy <= py && hy >= pny,
                2 => hy < py && hy >= pny && pny != py,
                _ => hy <= py && hy > pny && pny != py,
            };
            if cond {
                let x = px + (hy - py) * (pnx - px) / (pny - py);
                if x <= hx && x > qx {
                    qx = x;
                    if self.cfg.fhb_early && x == hx {
                        if hy == py {
                            return Some(p);
                        }
                        if hy == pny {
                            return Some(pn);
                        }
                    }
                    m = Some(if px < pnx { p } else { pn });
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }
        let m0 = m?;
        if hx == qx {
            return Some(if self.cfg.fhb_hxqx_mprev {
                self.nodes[m0].prev
            } else {
                m0
            });
        }
        let stop = m0;
        let mut m = m0;
        let mut tan_min = f64::INFINITY;
        p = self.nodes[m0].next;
        let mut guard = 0u64;
        while p != stop {
            guard += 1;
            if guard > 100000 {
                return None;
            }
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (mx, my) = (self.nodes[m].x, self.nodes[m].y);
            let hxok = !self.cfg.fhb_hx_neq || hx != px;
            if hx >= px
                && px >= mx
                && hxok
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px);
                let tie = match self.cfg.fhb_tie {
                    0 => px > mx,
                    1 => px > mx || (px == mx && self.sector_contains_sector(m, p)),
                    _ => px >= mx,
                };
                if self.locally_inside(p, hole) && (tan < tan_min || (tan == tan_min && tie)) {
                    m = p;
                    tan_min = tan;
                }
            }
            p = self.nodes[p].next;
        }
        Some(m)
    }

    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        self.area(self.nodes[m].prev, m, self.nodes[p].prev) < 0.0
            && self.area(self.nodes[p].next, m, self.nodes[m].next) < 0.0
    }

    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            let take = match self.cfg.leftmost {
                0 => {
                    self.nodes[p].x < self.nodes[leftmost].x
                        || (self.nodes[p].x == self.nodes[leftmost].x
                            && self.nodes[p].y < self.nodes[leftmost].y)
                }
                1 => self.nodes[p].x < self.nodes[leftmost].x,
                _ => self.nodes[p].x <= self.nodes[leftmost].x,
            };
            if take {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    fn point_in_triangle_node(&self, a: usize, b: usize, c: usize, p: usize) -> bool {
        point_in_triangle(
            self.nodes[a].x,
            self.nodes[a].y,
            self.nodes[b].x,
            self.nodes[b].y,
            self.nodes[c].x,
            self.nodes[c].y,
            self.nodes[p].x,
            self.nodes[p].y,
        )
    }

    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        self.nodes[self.nodes[a].next].i != self.nodes[b].i
            && self.nodes[self.nodes[a].prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b)
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b)
                && (self.area(self.nodes[a].prev, a, self.nodes[b].prev) != 0.0
                    || self.area(a, self.nodes[b].prev, b) != 0.0))
                || (self.equals(a, b)
                    && self.area(self.nodes[a].prev, a, self.nodes[a].next) > 0.0
                    && self.area(self.nodes[b].prev, b, self.nodes[b].next) > 0.0))
    }

    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        (self.nodes[q].y - self.nodes[p].y) * (self.nodes[r].x - self.nodes[q].x)
            - (self.nodes[q].x - self.nodes[p].x) * (self.nodes[r].y - self.nodes[q].y)
    }

    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        if (self.equals(p1, q1) && self.equals(p2, q2)) || (self.equals(p1, q2) && self.equals(p2, q1)) {
            return true;
        }
        (self.area(p1, q1, p2) > 0.0) != (self.area(p1, q1, q2) > 0.0)
            && (self.area(p2, q2, p1) > 0.0) != (self.area(p2, q2, q1) > 0.0)
    }

    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut guard = 0u64;
        loop {
            guard += 1;
            if guard > 100000 {
                return true;
            }
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let aprev = self.nodes[a].prev;
        let anext = self.nodes[a].next;
        if self.area(aprev, a, anext) < 0.0 {
            self.area(a, b, anext) >= 0.0 && self.area(a, aprev, b) >= 0.0
        } else {
            self.area(a, b, aprev) < 0.0 || self.area(a, anext, b) < 0.0
        }
    }

    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        let mut guard = 0u64;
        loop {
            guard += 1;
            if guard > 100000 {
                return false;
            }
            let pn = self.nodes[p].next;
            let (px_, py_) = (self.nodes[p].x, self.nodes[p].y);
            let (pnx, pny) = (self.nodes[pn].x, self.nodes[pn].y);
            if ((py_ > py) != (pny > py)) && pny != py_ && (px < (pnx - px_) * (py - py_) / (pny - py_) + px_) {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let a2 = self.new_node(ai, ax, ay);
        let b2 = self.new_node(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;
        self.nodes[a].next = b;
        self.nodes[b].prev = a;
        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;
        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;
        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;
        b2
    }

    fn new_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        let p = self.nodes.len();
        self.nodes.push(Node {
            i,
            x,
            y,
            prev: p,
            next: p,
            steiner: false,
        });
        p
    }

    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
        let p = self.new_node(i, x, y);
        if let Some(last) = last {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let pnext = self.nodes[p].next;
        let pprev = self.nodes[p].prev;
        self.nodes[pnext].prev = pprev;
        self.nodes[pprev].next = pnext;
    }
}

fn point_in_triangle(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64, px: f64, py: f64) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

fn build_polygon(n: i32) -> Vec<Vec<[f64; 2]>> {
    let mut polygon = Vec::new();
    for i in 0..n {
        let offset = (i * 2) as f64;
        let size = n as f64;
        polygon.push(vec![
            [offset, offset],
            [offset + size, offset],
            [offset + size, offset + size],
            [offset, offset + size],
        ]);
    }
    polygon
}

fn run_cfg(cfg: Cfg, n: i32) -> Vec<u32> {
    let polygon = build_polygon(n);
    let mut e = E {
        nodes: Vec::new(),
        indices: Vec::new(),
        vertices: 0,
        cfg,
        budget: Cell::new(0),
        depth: Cell::new(0),
    };
    e.run(&polygon);
    e.indices
}

fn expected(n: i32) -> &'static [u32] {
    match n {
        1 => &[2, 3, 0, 0, 1, 2],
        2 => &[0, 1, 7, 5, 3, 0],
        3 => &[0, 4, 7, 5, 4, 0, 0, 1, 2, 0, 2, 3],
        4 => &[5, 4, 0, 0, 1, 11, 7, 12, 15, 13, 12, 5, 0, 4, 7, 3, 0, 11],
        5 => &[9, 8, 0, 0, 4, 7, 1, 2, 3, 0, 8, 11, 3, 0, 7, 5, 4, 0, 0, 1, 3],
        6 => &[9, 8, 4, 0, 4, 7, 5, 4, 0, 0, 1, 15, 7, 16, 19, 17, 16, 5, 3, 0, 15, 0, 8, 11, 11, 20, 23, 21, 20, 9, 9, 4, 0],
        7 => &[1, 2, 3, 13, 12, 8, 0, 4, 7, 5, 4, 0, 0, 1, 3],
        8 => &[13, 12, 8, 0, 4, 7, 5, 4, 0, 0, 1, 19, 7, 20, 23, 21, 20, 5, 3, 0, 19],
        9 => &[1, 2, 3, 17, 16, 12, 0, 4, 7, 5, 4, 0, 0, 1, 3],
        10 => &[17, 16, 12, 0, 4, 7, 5, 4, 0, 0, 1, 23, 7, 24, 27, 25, 24, 5, 3, 0, 23],
        _ => &[],
    }
}

fn main() {
    let mut matches = 0;
    for reflex_strict in [false, true] {
        for block_strict in [false, true] {
            for hole_filter in 0..6u8 {
                for fhb_early in [false, true] {
                    for fhb_hxqx_mprev in [false, true] {
                        for fhb_hx_neq in [false, true] {
                            for fhb_tie in 0..3u8 {
                                for leftmost in 0..3u8 {
                                    for hole_forward in [false, true] {
                                        for outer_backward in [false, true] {
                                            for ray in 0..4u8 {
                                                for elim_ret_filtered in [false, true] {
                                                    let cfg = Cfg {
                                                        reflex_strict,
                                                        block_strict,
                                                        hole_filter,
                                                        fhb_early,
                                                        fhb_hxqx_mprev,
                                                        fhb_hx_neq,
                                                        fhb_tie,
                                                        leftmost,
                                                        hole_forward,
                                                        outer_backward,
                                                        ray,
                                                        elim_ret_filtered,
                                                    };
                                                    let mut ok = true;
                                                    for n in 1..=10 {
                                                        if run_cfg(cfg, n) != expected(n) {
                                                            ok = false;
                                                            break;
                                                        }
                                                    }
                                                    if ok {
                                                        matches += 1;
                                                        println!("MATCH: {:?}", cfg);
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    println!("total matches: {}", matches);
}

